from pathlib import Path
import json,itertools,collections
P=Path(__file__).resolve().parent
words=json.loads((P.parent/'words.json').read_text())['words'];by={w['word']:w for w in words}
centers=['эмоция','чувство','переживание','настроение','ощущение']
canon={w:w for w in by}
for row in json.loads((P.parent/'pair-audit/alias-clusters.json').read_text()):
 for w in row['members']:canon[w]=row['representative']
def split(s):return set(s.split(', ')) if s else set()
# Explicitly fixed meanings; criteria are semantic membership and expression,
# not all conceivable causes or effects of emotions.
definitions={
'эмоция':'Эмоциональный отклик или состояние, выражающее отношение к происходящему. Не только краткая реакция; устойчивые отношения оцениваются отдельно.',
'чувство':'Переживаемое душевное состояние или эмоциональное отношение в обычном русском употреблении. Не ограничено только длительными чувствами; органы чувств не включены.',
'переживание':'Субъективно проживаемое душевное состояние. Не только беспокойство и не просто внешнее событие.',
'настроение':'Относительно протяжённый эмоциональный фон. Не намерение или готовность выполнить действие.',
'ощущение':'Непосредственно чувствуемое телесное состояние. Переносное «ощущение одиночества» отмечается отдельно; не смешивается с телесным значением.'}
# These source families contain reactions rather than stable personal attitudes.
emotion_families=split('Радость, Счастье, Удовольствие, Восхищение, Подъём, Игривое возбуждение, Нежность, Ожидание, Облегчение, Удивление, Непонимание происходящего, Интерес, Волнение, Тревога, Страх, Трепет, Грусть, Тоска, Горе, Разочарование, Упадок, Безнадёжность, Обида, Раздражение, Гнев, Возмущение, Отвращение, Зависть и ревность, Злорадство, Стыд, Вина, Скука и пресыщение')
D={c:set() for c in centers};B={c:set() for c in centers}
D['эмоция']={w['word'] for w in words if w['layer']=='Ядро' and w['family'] in emotion_families}
# Remove cases more naturally called a condition, evaluation or disposition.
D['эмоция']-=split('самолюбие, самоуважение, робость, нервозность, неловкость, конфуз, угрызения, безысходность, обречённость, горечь, боль, безутешность, взбудораженность, меланхолия, хандра, пресыщение')
D['эмоция'] |= split('сочувствие, сострадание, жалость, сопереживание, благодарность, признательность, гордость')
core={w['word'] for w in words if w['layer']=='Ядро'}
D['чувство']=core-split('самолюбие, самодовольство, благосклонность, нервозность, замешательство, озадаченность, взбудораженность, меланхолия, хандра, расстройство, угнетённость, безутешность, неистовство, исступление, ожесточение, пресыщение, апатия, отрешённость, угрызения, конфуз')
D['переживание']=core-split('самолюбие, самоуважение, благосклонность, пренебрежение')
D['настроение']=split('веселье, приподнятость, воодушевление, благодушие, беззаботность, безмятежность, спокойствие, покой, умиротворение, грусть, печаль, уныние, меланхолия, хандра, тоска, подавленность, угнетённость, удручённость, раздражение, недовольство, озлобленность, враждебность, тревога, беспокойство, нервозность, увлечённость, скука')
# No pain-as-bodily move: original source fixes боль as emotional pain.
D['ощущение']=split('напряжение, расслабление, бодрость, усталость, вялость, разбитость, комфорт, дискомфорт, голод, истома')
# Candidate extensions and borderline labels. Do not silently call these synonyms.
extras={
'эмоция':'аффект, эйфория, дисфория, кринж, кайф, отрада, услада, нега, сокрушение, печалование, обескураженность, потрясение, оторопь, торжество',
'чувство':'защищённость, уязвимость, беспомощность, бессилие, неполноценность, ничтожность, принадлежность, уверенность, неуверенность, теплота, холодность, пустота, тяжесть, отрада, услада, нега, кринж, кайф, сокрушение, торжество',
'переживание':'защищённость, уязвимость, беспомощность, бессилие, неполноценность, ничтожность, принадлежность, уверенность, неуверенность, теплота, холодность, пустота, тяжесть, аффект, фрустрация, эйфория, дисфория, амбивалентность, стресс, дистресс, нега, истома, отрада, услада, обескураженность, потрясение, оторопь, торжество, кринж, кайф, драйв, мандраж, кручина, печалование, сокрушение',
'настроение':'радость, счастье, восторг, энтузиазм, задор, окрылённость, волнение, страх, гнев, злость, ненависть, неприязнь, отчаяние, опустошённость, апатия, безразличие, равнодушие, эйфория, дисфория, безучастность, безнадёжность, самодовольство',
'ощущение':'боль, горечь, пустота, тяжесть, теплота, холодность, жажда, истощение, бессилие, защищённость, одиночество, близость, тревога, страх, спокойствие, облегчение, удовольствие, наслаждение, блаженство, нега, влечение, возбуждение, комфорт, дискомфорт, дрожь, румянец'}
# Everyday dictionaries overlap. Stable attitudes aren't automatic emotions here.
for c in ['эмоция','чувство']:
 B[c]|=core-D[c]
for c,extra in extras.items(): B[c]|=split(extra)
# Conservative direct additions in the source's emotional meanings.
D['переживание'] |= split('обескураженность, потрясение, оторопь, торжество, отрада, услада, нега, сокрушение, кручина, печалование')
D['чувство'] |= split('беспомощность, защищённость, принадлежность, уверенность, неуверенность')
D['эмоция'] |= split('торжество, обескураженность')
for c in centers:B[c]-=D[c]
manifest=split('улыбка, смех, плач, слёзы, рыдание, всхлип, крик, вздох, дрожь, румянец')
# Expression is a separate relation, not a subtype. Keep it visible in counts.
X={c:set() for c in centers}
X['эмоция']=manifest
X['чувство']=manifest|split('объятие, поцелуй, ласка')
X['переживание']=manifest
X['настроение']=set()
X['ощущение']=set()

notes=[]
for c in centers:
 assert (D[c]|B[c]|X[c])<=set(by), (c,(D[c]|B[c]|X[c])-set(by))
 for w in words:
  n=w['word']
  if n in centers:continue
  if n in D[c]:
   score=2;relation='форма/содержание';reason=f'«{n}» в указанном смысле непосредственно обозначает форму или содержание понятия «{c}».'
  elif n in X[c]:
   score=2;relation='выражение';reason=f'«{n}» может непосредственно выражать {c}; по этому признаку нельзя однозначно установить конкретную эмоцию.'
  elif n in B[c]:
   score=1;relation='пограничное значение';reason=f'Для «{n}» связь с «{c}» зависит от длительности, контекста либо переносного/специального значения. В основной охват не включено.'
  else:
   score=0;relation='не включено в охват';reason=f'«{n}» не включено как прямая форма или выражение центра «{c}» в этом проходе. Другие отношения (например, возможная причина) здесь не проверяются.'
  notes.append({'center':c,'word':n,'representative':canon[n],'score':score,'relation':relation,'explanation':reason,'source_note':w['interpretation_note']})
# A complete 5 x 305 classification of this explicitly bounded relation question.
assert len(notes)==5*305
summary=[];sets={}
for c in centers:
 member={canon[n] for n in D[c]};expression={canon[n] for n in X[c]};sets[c]=member|expression
 summary.append({'center':c,'definition':definitions[c],'direct_original':len(D[c]|X[c]),'membership_representatives':len(member),'expression_representatives':len(expression-member),'direct_representatives':len(sets[c]),'borderline_representatives':len({canon[n] for n in B[c]}-sets[c]),'members':sorted(member),'expressions':sorted(expression-member),'borderline':sorted({canon[n] for n in B[c]}-sets[c])})
overlap=[]
for a,b in itertools.combinations(centers,2):
 both=sets[a]&sets[b];either=sets[a]|sets[b]
 overlap.append({'a':a,'b':b,'shared':len(both),'only_a':len(sets[a]-sets[b]),'only_b':len(sets[b]-sets[a]),'jaccard':round(len(both)/len(either),3),'shared_words':sorted(both)})
# Canonical merging applies across all cells; membership and borderline of aliases can conflict.
# Count direct if any fixed-sense member has direct annotation, and document this pooling.
(P/'classification.json').write_text(json.dumps(notes,ensure_ascii=False,indent=2)+'\n')
(P/'coverage.json').write_text(json.dumps({'centers':summary,'overlap':overlap,'pooling':'Union of fixed-sense alias groups inherited from prior audit; not proof of absolute synonymy.'},ensure_ascii=False,indent=2)+'\n')
lines=['# Пять центральных понятий: полный ограниченный проход','','## Задача и смысл чисел','','Проверены пять центров против остальных 305 слов исходного словника: 1 525 ячеек. Это авторская классификация **прямого охвата и выражения**, не поиск всех причинных, противопоставительных и других отношений. Ноль означает невключение по этому критерию, а не невозможность связи. Первая матрица 47 895 пар не переписана и не объявлена завершённой.','','Счётчики рассчитаны одинаковым способом по явным наборам. Это новая ограниченная классификация охвата; её числа нельзя напрямую сравнивать с неполной разметкой свободных отношений в предыдущем аудите. Это формализованная экспертная оценка; словари помогли определить значения центров, но не подтверждают каждую из 1 525 ячеек. Возраст, сложность и прежние шесть игровых типов не применялись.','','Синонимы объединены по 16 условным группам прошлого аудита. «Переживание» не сведено к тревоге, «чувство» не ограничено только устойчивой привязанностью. Для «ощущения» выбрана телесная сторона; переносные значения вынесены в пограничные. Это решение для сравнения, а не утверждение, что других значений у слова нет.','','## Покрытие','','| Центр | Прямых слов до объединения | Форм/содержаний после объединения | Выражений | Всего прямых представителей | Пограничных представителей |','|---|---:|---:|---:|---:|---:|']
for r in summary:lines.append(f'| {r["center"]} | {r["direct_original"]} | {r["membership_representatives"]} | {r["expression_representatives"]} | {r["direct_representatives"]} | {r["borderline_representatives"]} |')
lines+=['','## Смысл каждого центра','']
for r in summary:lines += [f'### {r["center"]}',r['definition'],'','Прямой охват: '+', '.join(r['members'])+'.','','Выражения: '+(', '.join(r['expressions']) or 'нет')+'.','','Пограничные: '+(', '.join(r['borderline']) or 'нет')+'.','']
lines+=['## Перекрытие прямого охвата','','Жаккар = общие партнёры / объединение партнёров. Не оценка качества, а мера совпадения наборов.','','| Центры | Общих | Только у первого | Только у второго | Жаккар |','|---|---:|---:|---:|---:|']
for r in overlap:lines.append(f'| {r["a"]} / {r["b"]} | {r["shared"]} | {r["only_a"]} | {r["only_b"]} | {r["jaccard"]:.1%} |')
lines+=['','## Вывод для замысла колоды','','Эмоция, чувство и переживание действительно являются центрами темы. Их широкое пересечение — свойство замысла, а не причина автоматически исключать слова. Однако эти три карты дают похожие старты; нельзя продавать их как три полностью разных области. Настроение выделяет эмоциональный фон. Ощущение добавляет телесную сторону, но исходный словник почти не содержит её конкретных названий. Поэтому малый охват ощущения частично вызван составом словника.','','Рабочая пятёрка кандидатов: эмоция, чувство, переживание, настроение, ощущение. Пока сохранить все пять: широкое перекрытие допустимо в пользовательском замысле, а окончательное решение зависит от будущего игрового состава. Не выдавать эти пять слов за пять непересекающихся категорий. До десяти не дополнять синонимами. Игра не изменена.','','Другие возможные стороны темы для отдельной проверки: состояние, отношение, реакция, выражение, желание. Первые четыре — новые слова относительно исходных 310, поэтому текущие показатели к ним не относятся. «Состояние» также может дублировать «переживание». Ни один новый кандидат пока не принят.','','## Источники значений и ограничения','','- [Эмоция — словари Грамоты](https://gramota.ru/poisk?mode=slovari&query=Эмоции): эмоциональная реакция или внутреннее состояние; в общеязыковых толкованиях сближается с чувством.\n- [Настроение — словари Грамоты](https://gramota.ru/poisk?mode=slovari&query=Настроение): эмоциональный фон допускает разные конкретные состояния.\n- [Чувствовать — словари Грамоты](https://gramota.ru/poisk?mode=slovari&query=чувствовать): употребляется и для душевных, и для физических состояний; не обосновывает жёсткую границу «эмоция короткая / чувство долгое».\n- [Ощущать — словари Грамоты](https://gramota.ru/poisk?mode=slovari&query=ощущаешь): различаются сенсорное восприятие и более широкое переживание состояния.\n- [Исследование значений ощущать/чувствовать](https://www.gramota.net/article/phil20200098/pdf): подтверждает многозначность и пересечение соответствующих слов.','','Использованы доступные индексированные словарные выдержки. Прямые запросы к отдельным статьям «чувство», «ощущение», «переживание» вернули 403; полной сверки всех статей не заявляем. Все группировки и численные результаты — собственная разметка. Нельзя считать их независимой статистикой носителей языка.','','## Файлы','','- [Все 1 525 ячеек с объяснениями](classification.json).\n- [Покрытие и пересечения](coverage.json).\n- [Компактная матрица 305 × 5](matrix.md).\n- [Воспроизводимый расчёт](build.py).']
(P/'README.md').write_text('\n'.join(lines)+'\n')
lines=['# Матрица охвата: 305 слов × 5 центров','','2 — прямая форма/содержание или выражение; 1 — погранично; 0 — не включено по этим отношениям. Это не отрицание любых связей. В JSON различены форма и выражение.','','| Слово | Эмоция | Чувство | Переживание | Настроение | Ощущение |','|---|---:|---:|---:|---:|---:|']
lookup={(r['word'],r['center']):r['score'] for r in notes}
for w in words:
 if w['word'] in centers:continue
 lines.append('| '+w['word']+' | '+' | '.join(str(lookup[w['word'],c]) for c in centers)+' |')
(P/'matrix.md').write_text('\n'.join(lines)+'\n')
print([(r['center'],r['direct_representatives'],r['borderline_representatives']) for r in summary])
print([(r['a'],r['b'],r['shared'],r['only_a'],r['only_b']) for r in overlap])
